import {
    type Diagnostic,
    type File,
    FileSystem,
    GUID,
    path,
    type Telemetry,
    type TelemetryEvent,
    unzipAppPackage,
    zipDirectory,
    TelemetryFactory,
} from '@servicenow/sdk-build-core'
import { REPACK_OUTPUT_DIR } from '@servicenow/sdk-build-plugins'
import Handlebars from 'handlebars'
import snakeCase from 'lodash/snakeCase'
import * as os from 'os'
import { Connector, type IConnector, type UnloadedRecord } from './connector'
import { LazyCredential } from './credentials'
import { ApplicationDependencies } from './orchestrator/dependencies'
import { TrackerStatus, Uninstaller } from './orchestrator/uninstaller'
import type { Project, TransformResult } from './project'
import { ProjectFactory, renderTemplates, type TemplateFile, templates, type Templates } from './project-factory'
import {
    createDirIfNotExists,
    runScriptInProject,
    defaultDownloadDir,
    type TransformOptions,
    writeFileStream,
    traverseDirectory,
    uiPrebuild,
    uiPostbuild,
} from './util'

const UPDATE_XML_TRANSFORM_LIMIT_DEFAULT = 2000

/**
 * The Orchestrator class is responsible for managing and coordinating the lifecycle of
 * a project, including the build, packaging, and installation processes.
 */
export class Orchestrator {
    private readonly telemetry: Telemetry
    private readonly credential?: LazyCredential
    private readonly connector?: IConnector

    constructor(
        private readonly project: Project,
        credentialOrConnector?: LazyCredential | IConnector
    ) {
        this.telemetry = project.getTelemetryClient() ?? TelemetryFactory.create()
        if (credentialOrConnector instanceof LazyCredential) {
            this.credential = credentialOrConnector
            this.connector = new Connector(credentialOrConnector)
        } else if (credentialOrConnector) {
            this.connector = credentialOrConnector
        }
    }

    private getConnector() {
        if (!this.connector) {
            throw new Error(
                'No credentials or connector provided to Orchestrator. Operations requiring instance access need authentication.'
            )
        }

        return this.connector
    }

    /**
     * Build the project, generate the output files, and save the keys registry.
     *
     * @param frozenKeys If true, an error will be thrown if any changes to the keys registry are detected.
     * @param sysIds If provided, build output will only include records matching this array
     * @returns The output files.
     */
    public async build(options: { frozenKeys?: boolean; sysIds?: string[] | undefined } = {}): Promise<BuildResult> {
        const telemetryTimer = this.telemetry.startTimerEvent('build')
        let metricsData: TelemetryEvent[] | undefined
        try {
            const { frozenKeys = false } = options
            this.clean()

            const logger = this.project.getLogger()
            const config = this.project.getConfig()

            await uiPrebuild({ project: this.project })

            const keysFile = this.project.getKeys().getSourceFile()
            const keysContentBefore = keysFile.getFullText()

            const buildIdsSet = options.sysIds ? new Set(options.sysIds) : undefined

            let files: File[]
            try {
                files = await this.project.saveOutput(buildIdsSet)
            } catch (e) {
                logger.error(e)

                metricsData = [
                    telemetryTimer.end({
                        appInfo: { scopeId: config.scopeId },
                        data: {
                            success: false,
                            scopeId: config.scope,
                        },
                    }),
                ]

                return {
                    success: false,
                    diagnostics: [],
                }
            }

            this.project
                .getPlugins()
                .toArray()
                .forEach((plugin) => {
                    plugin.flushCache()
                })

            if (frozenKeys) {
                const keysContentAfter = keysFile.getFullText()

                // In CI Mode, we want to ensure that the keys file is up-to-date.
                // Keys.ts file is reconstructed during build process even if there are no changes
                // to the keys file, that's why we need to compare the content of the keys file
                if (keysContentBefore !== keysContentAfter) {
                    throw new Error('Keys file is out-of-date. To update it, run the build again without frozen keys.')
                }
            }

            await this.project.getKeys().getSourceFile().save() // Saves the keys file

            await uiPostbuild({ project: this.project })

            metricsData = [
                telemetryTimer.end({
                    appInfo: { scopeId: config.scopeId },
                    data: {
                        success: true,
                        scopeId: config.scopeId,
                    },
                }),
            ]

            return {
                success: true,
                files,
                packOutput: this.project.resolvePath(config.packOutputDir), // TODO: Remove after 4.0
                diagnostics: [],
            }
        } catch (error) {
            this.telemetry.error('build', error)
            throw error
        } finally {
            if (metricsData) {
                this.telemetry.sendEvent(metricsData)
            }
        }
    }

    /**
     * Cleans the build appOutDir and packOutputDir of the project.
     */
    public clean(): void {
        const { appOutputDir, packOutputDir, staticContentDir } = this.project.getConfig()
        const workingDir = this.project.getRootDir()
        const fs = this.project.getFileSystem()

        /**
         * Clean REPACK_OUTPUT_DIR at the beginning of the build so,
         * - DEF0676063 - we don't package stale data from older builds
         * - DEF0702536 - we don't clean up the build files between subsequent `toRecord` calls inside server-module plugin
         */
        fs.rmSync(path.join(workingDir, REPACK_OUTPUT_DIR), {
            recursive: true,
            force: true,
        })
        fs.rmSync(path.join(workingDir, appOutputDir), {
            recursive: true,
            force: true,
        })
        fs.rmSync(path.join(workingDir, packOutputDir), {
            recursive: true,
            force: true,
        })
        fs.rmSync(path.join(workingDir, staticContentDir), {
            recursive: true,
            force: true,
        })
    }

    /**
     * Generate a ZIP archive containing the project's output which can be installed with `install` method
     * @param packagePath The path where the ZIP archive will be saved. Defaults to `packOutputDir/{package name_version}.zip`.
     * @returns The path to the generated ZIP archive.
     */
    public async pack(
        packagePath: string = this.project.resolvePath(
            this.project.getConfig().packOutputDir,
            `${snakeCase(`${this.project.getPackage().name}_${this.project.getPackage().version}`)}.zip`
        )
    ): Promise<string> {
        const { appOutputDir } = this.project.getConfig()
        const workingDir = this.project.getRootDir()

        const logger = this.project.getLogger()
        logger.debug(`packing directory ${appOutputDir} to ${packagePath}`)

        const fs = this.project.getFileSystem()
        if (FileSystem.existsSync(fs, packagePath)) {
            fs.rmSync(packagePath, { recursive: true, force: true })
        }

        fs.mkdirSync(path.dirname(packagePath), { recursive: true })

        await zipDirectory(fs, path.join(workingDir, appOutputDir), packagePath)
        return packagePath
    }

    /**
     * Unpacks a ZIP archive containing ServiceNow application files
     *
     * @param zipPath The path to the ZIP archive.
     * @param targetPath The path where the files will be extracted.
     * @returns The list of files extracted from the ZIP archive.
     */
    public unpack(zipPath: string, targetPath: string): Promise<{ files: string[] }> {
        const fs = this.project.getFileSystem()
        const logger = this.project.getLogger()
        logger.debug(`unpacking directory ${zipPath} to ${targetPath}`)
        return unzipAppPackage(fs, zipPath, targetPath)
    }

    private async transform0(options: TransformPaths | DownloadOptions | TransformOptions): Promise<TransformResult> {
        let files: string[] = []
        let tempMetaFiles: string | undefined

        const fileSystem = this.project.getFileSystem()
        const config = this.project.getConfig()

        if ('updateSetId' in options) {
            tempMetaFiles = defaultDownloadDir()

            const updateCount = await this.getConnector().getUpdateXMLCount(options.updateSetId)
            const updateLimit = options.maxUpdateCount ?? UPDATE_XML_TRANSFORM_LIMIT_DEFAULT
            if (updateCount > updateLimit) {
                throw new Error(
                    `Update Set contains more than ${updateLimit} records (${updateCount}). To transform this many updates, please supply a higher limit using '--maxUpdateCount'`
                )
            }
            const updateSet = await this.download(options, tempMetaFiles)
            files = [updateSet]
        } else if ('paths' in options) {
            files = Array.isArray(options.paths) ? options.paths : [options.paths]
        } else if ('sysId' in options || 'sysIds' in options) {
            let metadataFiles: UnloadedRecord[]
            if ('table' in options) {
                const appDependencies = new ApplicationDependencies(this.project, this.getConnector())
                metadataFiles = await appDependencies.fetchRelatedRecords(options.table, options.sysId)
            } else {
                metadataFiles = await this.getConnector().unloadRecords(options.sysIds, config.scopeId)
                if (metadataFiles.length === 0) {
                    throw new Error(`No records found on instance in scope for provided sysIds`)
                } else if (metadataFiles.length !== options.sysIds.length) {
                    this.project
                        .getLogger()
                        .warn(
                            `Failed to download records for the following IDs: ${options.sysIds.filter((id) => !metadataFiles.find((r) => r.sysId === id)).join(', ')}`
                        )
                }
            }
            tempMetaFiles = defaultDownloadDir()
            FileSystem.ensureDirSync(fileSystem, tempMetaFiles)
            metadataFiles.forEach((file) => {
                const filePath = path.join(tempMetaFiles as string, `${file.tableName}_${file.sysId}.xml`)
                fileSystem.writeFileSync(filePath, file.content)
                files.push(filePath)
            })
        } else if (config.type === 'configuration') {
            throw new Error(
                'Transform/Sync for a configuration project must provide either table and id of records to transform, or an updateSet ID'
            )
        } else {
            const metadataPack = await this.download('method' in options ? options : undefined)

            tempMetaFiles = defaultDownloadDir()

            const metadataFiles = await this.unpack(metadataPack, tempMetaFiles)

            fileSystem.rmSync(metadataPack, { recursive: true, force: true })

            files = metadataFiles.files
        }

        const transformResult = await this.project.transform(files, options)

        if (tempMetaFiles) {
            fileSystem.rmSync(tempMetaFiles, { recursive: true, force: true })
        } else {
            for (const path of transformResult.handledPaths) {
                // Delete xml sources only if transforming from path in metadata dir
                if (this.project.isInMetadataDir(path)) {
                    this.project.removeFile(path)
                    fileSystem.rmSync(path, { recursive: true, force: true })
                }
            }
        }

        this.project.save()

        return transformResult
    }

    /**
     * Transforms the project's metadata files.
     *
     * @param options Options for the transform process
     * @returns The transformed files
     */
    public async transform(options?: TransformPaths | DownloadOptions | TransformOptions): Promise<TransformResult> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('transform')
            const config = this.project.getConfig()
            const transformResult = await this.transform0(options ?? {})
            this.telemetry.sendEvent(
                telemetryTimer.end({
                    appInfo: { scopeId: config.scopeId },
                    data: {
                        transformedMetadataCount: transformResult ? transformResult.changedFiles.length : 0,
                        mode: options && 'method' in options ? options.method : undefined,
                        local: options && 'paths' in options ? !!options.paths : false,
                        updateSet: options && 'updateSetId' in options,
                    },
                })
            )
            return transformResult
        } catch (error) {
            this.telemetry.error('transform', error)
            throw error
        }
    }

    public async uploadXMLFiles(filePaths: string[], options?: { targetUpdateSetId?: string }): Promise<string> {
        const connector = this.getConnector()
        const fs = this.project.getFileSystem()
        const { scopeId } = this.project.getConfig()
        const files: { blob: Blob; name: string }[] = []
        for (const filePath of filePaths) {
            if (FileSystem.existsSync(fs, filePath)) {
                const fileStat = fs.statSync(filePath)
                if (fileStat.isFile()) {
                    files.push({
                        blob: new Blob([fs.readFileSync(filePath) as unknown as BlobPart], {
                            type: 'application/xml',
                        }),
                        name: path.basename(filePath),
                    })
                } else {
                    throw new Error(`Expected file, received directory: ${filePath}.`)
                }
            } else {
                throw new Error(`File ${filePath} does not exist.`)
            }
        }
        return await connector.uploadXmlFiles(scopeId, files, options)
    }

    /**
     * Install the project on the connected ServiceNow instance.
     *
     * @param clean If true, the app will be removed from the instance before being installed again.
     * @param packageZipPath The path to the package zip file to install. If not provided, the project will be packed first.
     */
    public async install(options?: {
        clean?: boolean
        packageZipPath?: string
        installAsStoreApp?: boolean
        installAsync?: boolean
        demoData?: boolean
    }): Promise<void> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('install')
            const { scope, scopeId } = this.project.getConfig()
            const { version } = this.project.getPackage()
            const { id: previousInstallId } = await this.installStatus()

            const connector = this.getConnector()
            const scopeInfo = await connector.getScopeInfo(scope, scopeId)
            const isStoreApp = scopeInfo?.sysClassName === 'sys_store_app'
            const logger = this.project.getLogger()

            if (scopeInfo && !options?.clean && Boolean(options?.installAsStoreApp) !== isStoreApp) {
                throw new Error(
                    `Attempting to install ${options?.installAsStoreApp ? 'a store app' : 'an app'} record but there is already a ${isStoreApp ? 'sys_store_app' : 'sys_app'} record for this scope present on the instance. Install with flag '--reinstall' (-r) to delete existing app and reinstall`
                )
            }

            // if the app is not installed, we can skip the uninstall step
            if (scopeInfo && options?.clean) {
                logger.info(`Uninstalling application ${scopeInfo?.appId ?? ''} for clean installation...`)
                logger.warn(
                    `This operation may cause unintended removal of metadata created by other developers on your instance. When reinstalling, any application metadata on your instance that isn't present in the local application installation package generated by $now-sdk build will be removed during the uninstall process. If there is metadata that's out of sync with your local application, use $now-sdk transform to synchronize your local metadata with the metadata on your instance.`
                )
                await new Uninstaller(connector, logger).process(scope, scopeId, isStoreApp)
            }

            let packageZipPath = options?.packageZipPath
            if (!packageZipPath) {
                packageZipPath = await this.pack()
            }

            const fs = this.project.getFileSystem()

            if (!FileSystem.existsSync(fs, packageZipPath)) {
                throw new Error(
                    `Installation failed due to missing installation artifact '${packageZipPath}'. Run $now-sdk build before running $now-sdk install to generate a build artifact for installation.`
                )
            }

            const buffer = fs.readFileSync(packageZipPath)
            const file = new Blob([new Uint8Array(buffer)])

            logger.debug(`installing package ${packageZipPath}`)

            const result = await connector.uploadScopedAppPackage(file, {
                loadDemoData: options?.demoData ?? true,
                isStoreApp: isStoreApp || !!options?.installAsStoreApp,
                registerScope: false, // FIXME: Does not work on earlier glide builds
                installAsync: options?.installAsync ?? false,
                appInfo: {
                    scope,
                    scopeId,
                    version,
                },
            })

            if (result?.trackerId) {
                let installSuccessful = false
                let errorMessage = ''
                let attempt = 0
                while (true) {
                    const { status, status_message } = await connector.getProgress(result?.trackerId)
                    if (status === TrackerStatus.ERROR || status === TrackerStatus.SUCCESSFUL) {
                        installSuccessful = status === TrackerStatus.SUCCESSFUL
                        errorMessage = status_message
                        break
                    }
                    await new Promise((resolve) => setTimeout(resolve, 1000))
                    attempt += 1
                    if (attempt % 30 === 0) {
                        logger.info(`App install pending${status_message ? `, waiting on ${status_message}` : '...'}`)
                    }
                }
                if (installSuccessful) {
                    logger.info(
                        `Rollback (undo installation): ${connector.getHost().origin}/sys_rollback_context.do?sys_id=${result.rollbackId}`
                    )
                } else {
                    throw new Error(errorMessage)
                }
            } else {
                let checkCount = 0
                let installStatus:
                    | {
                          finished: boolean
                          id: string
                      }
                    | undefined

                while (checkCount < 30) {
                    installStatus = await this.installStatus()
                    if (installStatus?.finished && installStatus.id !== previousInstallId) {
                        break
                    }

                    await new Promise((resolve) => setTimeout(resolve, 1000))
                    checkCount++
                }

                if (!installStatus || !installStatus.finished || installStatus.id === previousInstallId) {
                    throw new Error(
                        `Could not determine app installation status. Check instance to verify installation.`
                    )
                }
            }

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: {
                        appInfo: { scopeId },
                        data: { isInstalled: true },
                    },
                })
            )
        } catch (error) {
            this.telemetry.error('install', error)
            throw error
        }
    }

    /**
     * Generates sys_claim records on the instance to mark desired records as moved into this global app
     *
     * @param sysIds Array of sysIds to move to the app
     */
    public async moveToApp(options: { sysIds: string[] }) {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('move.to-app')
            const { sysIds } = options
            const { scope, scopeId } = this.project.getConfig()

            if (scope !== 'global') {
                throw Error(`Only Global apps can customize files by moving them into the app`)
            }

            const connector = this.getConnector()
            const logger = this.project.getLogger()

            const scopeInfo = await connector.getScopeInfo(scope, scopeId)
            if (!scopeInfo) {
                throw Error(
                    `App ${scopeId} must be present on the instance to move files. Run 'now-sdk install' to install app.`
                )
            }

            const claimed = await connector.moveToApp(sysIds, scopeId)

            if (claimed.length === 0) {
                logger.info(`Moved 0 files. Please ensure files are valid records`)
                return
            }

            logger.info(`Successfully moved ${claimed.length} file(s) to app`)

            const claimedIds = claimed.map((claim) => claim.sysId)
            const failedToClaim = sysIds.filter((id) => !claimedIds.includes(id))
            if (failedToClaim && failedToClaim.length > 0) {
                logger.warn(`Failed to move:\n ${failedToClaim.join('\n\t')}`)
            }

            const result = await this.transform0({
                method: 'incremental',
            })

            this.project.save()
            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: {
                        appInfo: { scope: scopeId },
                        data: {},
                    },
                })
            )
            return result
        } catch (error) {
            this.telemetry.error('move.to-app', error)
            throw error
        }
    }

    public async installConfigurations(options?: { targetUpdateSetId?: string }): Promise<string> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('install.configurations')
            const files: string[] = []
            const { appOutputDir, scopeId } = this.project.getConfig()
            const outputDir = this.project.resolvePath(appOutputDir)
            traverseDirectory(this.project.getFileSystem(), outputDir, {
                extensions: ['.xml'],
                visitor: (file) => {
                    files.push(file)
                },
            })

            const updateSetId = await this.uploadXMLFiles(
                files,
                options?.targetUpdateSetId ? { targetUpdateSetId: options.targetUpdateSetId } : undefined
            )
            this.telemetry.sendEvent(
                telemetryTimer.end({
                    data: {
                        appInfo: { scopeId },
                        data: { isInstalled: true },
                    },
                })
            )

            return updateSetId
        } catch (error) {
            this.telemetry.error('install.configurations', error)
            throw error
        }
    }

    /**
     * Returns the last status of the app upgrade.
     */
    public async installStatus(): Promise<{
        finished: boolean
        id: string
    }> {
        const { scope } = this.project.getConfig()

        const connector = this.getConnector()

        return await connector.appUpgradeStatus(scope)
    }

    /**
     * Download the app contents from the connected ServiceNow instance.
     *
     * @param options Options for the download process, defaults to `{ method: 'complete' }`
     * @param downloadPath The path where the downloaded files will be saved. Defaults to `os.tmpdir()/servicenow/download/GUID()`.
     * @returns The path to the downloaded zip file.
     */
    public async download(
        options: Exclude<Exclude<DownloadOptions, DownloadMetadataOptions>, DownloadIDOptions> = {
            method: 'complete',
        },
        downloadPath: string = path.join(os.tmpdir(), 'servicenow/download', GUID())
    ): Promise<string> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('download')
            const connector = this.getConnector()

            const { scope, scopeId } = this.project.getConfig()

            let result: Response

            const logger = this.project.getLogger()

            if (options.method === 'update-set') {
                logger.info(`downloading update set ${options.updateSetId}`)
                result = await connector.downloadUpdateSet(options.updateSetId, scopeId)
            } else {
                logger.info(`downloading package for ${scope} ${options.method}`)
                result = await connector.download(scopeId, options)
            }

            if (!result.ok || !result.body) {
                const body = await result.json()
                if (body && typeof body.result === 'string') {
                    throw new Error(body.result)
                }
                throw new Error(`Failed to download package for ${scope}`)
            }

            const fs = this.project.getFileSystem()

            let writePath: string
            if (options.method === 'update-set') {
                writePath = path.join(downloadPath, `sys_remote_update_set.xml`)
            } else {
                writePath = path.join(downloadPath, `${scopeId}-${options.method}.zip`)
            }

            createDirIfNotExists(downloadPath, fs)

            await writeFileStream(fs, writePath, result.body)

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    appInfo: { scopeId },
                    data: {
                        completeAppDownload: options.method === 'complete',
                    },
                })
            )

            return writePath
        } catch (error) {
            this.telemetry.error('download', error)
            throw error
        }
    }

    /**
     * Downloads and generates TypeScript type definitions for dependencies from a ServiceNow instance.
     *
     * This method can download two types of definitions:
     * - **Script definitions**: TypeScript definitions for ServiceNow APIs (glide.*.d.ts files)
     * - **Fluent types**: TypeScript definitions for configured dependencies from now.config.json
     *
     * @param options - Configuration options for what to download
     * @param options.downloadScripts - Download script type definitions (default: true)
     * @param options.downloadFluent - Download fluent type definitions from now.config.json (default: true)
     *
     * @example
     * ```typescript
     * // Download all dependencies (default)
     * await orchestrator.types()
     *
     * // Download only script definitions
     * await orchestrator.types({ downloadScripts: true, downloadFluent: false })
     *
     * // Download only fluent types
     * await orchestrator.types({ downloadScripts: false, downloadFluent: true })
     * ```
     *
     * @throws {Error} If fetching or generating types fails
     *
     * @see {@link addDependency} for adding new dependencies programmatically
     */
    public async types(options?: { downloadScripts?: boolean; downloadFluent?: boolean }): Promise<void> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('dependencies')
            const { downloadScripts = true, downloadFluent = true } = options || {}
            const logger = this.project.getLogger()
            const appDependencies = new ApplicationDependencies(this.project, this.getConnector())

            if (downloadScripts) {
                logger.info('Processing script type definitions...')
                await appDependencies.addScriptDefinitions()
            }

            if (downloadFluent) {
                logger.info('Processing fluent type dependencies...')
                await appDependencies.addFluentTypes()
            }
            this.telemetry.sendEvent(telemetryTimer.end())
        } catch (error) {
            this.telemetry.error('dependencies', error)
            throw error
        }
    }

    /**
     * Adds new dependency items to the project and updates now.config.json.
     *
     * This method:
     * 1. Updates now.config.json with the new dependency items
     * 2. Fetches the records from the ServiceNow instance
     * 3. Generates TypeScript type definitions
     * 4. Updates index files
     *
     * Supports adding dependencies from any ServiceNow table, with special handling for:
     * - **Flow items**: actions, triggers, subflows (stored in dependencies.<scope>.automation.*)
     * - **Tables**: Table definitions (stored in dependencies.<scope>.tables)
     * - **Custom records**: Any other table (stored in dependencies.<scope>.<table_name>)
     *
     * @param options - Configuration for the dependency to add
     * @param options.table - Table name or alias (e.g., 'actions', 'sys_security_acl', 'sys_user')
     * @param options.ids - Array of sys_ids or table names. Use ['*'] to fetch all records from a scope
     * @param options.scope - Scope filter (e.g., 'global', 'x_my_app'). Required when using wildcard '*'
     *
     * @example
     * ```typescript
     * // Add specific flow actions
     * await orchestrator.addDependency({
     *     table: 'actions',
     *     ids: ['action_id1', 'action_id2']
     * })
     *
     * // Add all actions from a scope using wildcard
     * await orchestrator.addDependency({
     *     table: 'actions',
     *     ids: ['*'],
     *     scope: 'global'
     * })
     *
     * // Add specific security ACLs
     * await orchestrator.addDependency({
     *     table: 'sys_security_acl',
     *     ids: ['acl_id1', 'acl_id2']
     * })
     *
     * // Add all ACLs from a custom scope
     * await orchestrator.addDependency({
     *     table: 'sys_security_acl',
     *     ids: ['*'],
     *     scope: 'x_my_app'
     * })
     *
     * // Add table definitions
     * await orchestrator.addDependency({
     *     table: 'tables',
     *     ids: ['incident', 'problem', 'change_request']
     * })
     * ```
     *
     * @throws {Error} If wildcard '*' is used without a scope
     * @throws {Error} If fetching records from the instance fails
     * @throws {Error} If updating now.config.json fails
     *
     * @see {@link types} for downloading existing dependencies
     */
    public async addDependency(options: { table: string; ids: string[]; scope: string }): Promise<void> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('dependencies.add')
            const logger = this.project.getLogger()
            const appDependencies = new ApplicationDependencies(this.project, this.getConnector())
            logger.info(`Adding ${options.table}: ${options.ids.join(', ')} (scope: ${options.scope})`)

            await appDependencies.addDependencyItems(options.table, options.ids, options.scope)

            logger.info(`Successfully added ${options.ids.length} ${options.table} records`)
            this.telemetry.sendEvent(telemetryTimer.end())
        } catch (error) {
            this.telemetry.error('dependencies.add', error)
            throw error
        }
    }

    public async run(options: { script: string }): Promise<void> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('run')
            const { scopeId } = this.project.getConfig()
            const scriptName = options.script
            await runScriptInProject({
                scriptName,
                project: this.project,
                credential: this.credential,
                throwIfNotFound: true,
            })
            this.telemetry.sendEvent(
                telemetryTimer.end({
                    appInfo: { scopeId },
                })
            )
        } catch (error) {
            this.telemetry.error('run', error)
            throw error
        }
    }

    /**
     * Applies a template to the project.
     * @param id The ID of the template to apply.
     * @returns The temlate files that were applied to the project
     */
    public async applyTemplate(id: keyof Templates, params?: Record<string, string>): Promise<TemplateFile[]> {
        try {
            const telemetryTimer = this.telemetry.startTimerEvent('init.apply-template')

            const config = this.project.getConfig()
            const template = templates[id]
            if (!template) {
                throw new Error(`Template ${id} not found`)
            }
            const projectFactory = new ProjectFactory(this.project.getFileSystem())

            const renderedTemplates = renderTemplates(
                template.files,
                { ...config, ...params },
                projectFactory.getOriginalFiles(this.project.getRootDir())
            )
            for (const { path, content, templateFile } of renderedTemplates) {
                const existing = this.project.getFileIfExists(path)
                if (existing) {
                    //Check if the template can be merged and throw if not
                    const params = Handlebars.parseWithoutProcessing(templateFile.content)
                    if (!params.body.some((b) => (b as hbs.AST.BlockStatement).path?.original === 'mergeJsonFiles')) {
                        throw new Error(`Collision detected with template file that is not mergable: ${path}`)
                    }
                    existing.setContent(content)
                } else {
                    this.project.addFile({ path, content })
                }
            }
            this.project.save()

            this.telemetry.sendEvent(
                telemetryTimer.end({
                    appInfo: { scopeId: config.scopeId },
                    data: { existing: true, templateId: id, ...params },
                })
            )

            return renderedTemplates
        } catch (error) {
            this.telemetry.error('init.apply-template', error, {
                existing: true,
                ...{ templateId: id, ...params },
            })
            throw error
        }
    }

    /**
     * @deprecated Diagnostics are logged automatically
     */
    public logDiagnostics(_diagnostics: Diagnostic[], _options: { colors?: boolean } = { colors: true }): void {}

    /**
     * Get documentation metadata for all APIs provided by loaded plugins.
     * Returns a manifest mapping API names to their documentation paths and tags.
     * Uses isomorphic module resolution that works in both Node.js and browser environments.
     */
    public async getDocsMetadata() {
        return this.project.getDocsMetadata()
    }
}

export type DownloadCompleteOptions = {
    method: 'complete'
}

export type DownloadIncrementalOptions = {
    method: 'incremental'
    lastPull?: string
}

export type DownloadUpdateSetOptions = {
    method: 'update-set'
    updateSetId: string
    maxUpdateCount?: number
}

export type DownloadIDOptions = {
    method: 'sys-id'
    sysIds: string[]
}

export type DownloadMetadataOptions = {
    method: 'metadata'
    sysId: string
    table: string
}

export type TransformPaths = TransformOptions & {
    paths: string[] | string
}

export type DownloadOptions = TransformOptions &
    (
        | DownloadCompleteOptions
        | DownloadIncrementalOptions
        | DownloadUpdateSetOptions
        | DownloadMetadataOptions
        | DownloadIDOptions
    )

export type BuildResult = BuildResultSuccess | BuildResultError

export type BuildResultSuccess = {
    success: true
    files: File[]
    packOutput: string

    /**
     * @deprecated
     */
    diagnostics: Diagnostic[]
}

export type BuildResultError = {
    success: false

    /**
     * @deprecated
     */
    diagnostics: Diagnostic[]
}
